mapper.insert:
INSERT INTO comments (
    id, post_id, parent_id, root_id, user_id, content, status, is_top,
    reply_count, create_time, update_time
) VALUES (
    #{id}, #{postId}, #{parentId}, #{rootId}, #{userId}, #{content}, #{status}, #{isTop},
    #{replyCount}, #{createTime}, #{updateTime}
)

mapper.select:
SELECT c.*, u.nickname AS author_nickname, u.avatar AS author_avatar,
       0 AS is_assistant
FROM comments c
JOIN users u ON c.user_id = u.id
WHERE c.post_id = #{postId}
  AND c.parent_id IS NULL
  AND c.status = 'published'

  AND c.id < #{cursor}

ORDER BY c.is_top DESC, c.id DESC
LIMIT #{size}

SELECT c.*, u.nickname AS author_nickname, u.avatar AS author_avatar,
       0 AS is_assistant
FROM comments c
JOIN users u ON c.user_id = u.id
WHERE c.parent_id = #{parentId}
  AND c.status = 'published'

  AND c.id > #{cursor}

ORDER BY c.id ASC
LIMIT #{size}
